use xiom.io;

use xiom.string;
fn main() -> Int {
  let items: Vec[Str] = Vec[Str].new();
  let prices: Map[Str,Float64] = Map[Str,Float64].new();
  let categories: Set[Str] = Set[Str].new();

  items.push("Widget");
  prices.insert("Widget", 9.99);
  categories.insert("hardware");

  items.push("Gadget");
  prices.insert("Gadget", 14.99);
  categories.insert("electronics");

  items.push("Widget");
  categories.insert("hardware");

  io.println("Total items: " + string.int_to_str(items.len()));
  io.println("Categories: " + string.int_to_str(categories.len()));

  match prices.get("Gadget") {
    Some(p) -> io.println("Gadget: $" + string.float_to_str(p));
    None -> io.println("Gadget not found");
  }

  return 0;
}
